// === Tab: ineinanderdrehendekreise_op.pde ===
let i;

let kreise = 23;

let ersterdurchmesser = 300;
let durchmesserdifferenz = 13;

let xVersatz = 13;
let yVersatz;

let geschwindigkeit = 0.002;

function setup()
{
  frameRate(30);
  createCanvas(900, 563);
  textFont(createFont("Sans", 11));
  smooth();
  noStroke();
}

function draw()
{
  background(255);
  translate(width/2, height/2);
  push();
  rotate(i);
  for(let j = 0; j < kreise; j++)
  {
    if(j % 2 == 0) fill(239, 239, 212); else fill(42, j * 185/kreise, 84);
    rotate(i);
    ellipse(0, 0, ersterdurchmesser - j * durchmesserdifferenz, ersterdurchmesser - j * durchmesserdifferenz);
    translate(xVersatz, yVersatz);
  }
  pop();
  i += geschwindigkeit;
  translate(-width/2, -height/2);
  fill(84);
  text("Press \'1\' for preset one (default) or \'2\' for preset two!", 20, 18);
}

function keyPressed()
{
  if(key == '1')
  {
    kreise = 23;
    durchmesserdifferenz = 13;
    xVersatz = 13;
    geschwindigkeit = 0.002;
  }
  if(key == '2')
  {
    kreise = 30;
    durchmesserdifferenz = 10;
    xVersatz = 90;
    geschwindigkeit = 0.002;
  }
}
